Journaux Caddy → CloudWatch : adapter la config Caddy ou pousser les fichiers de log via script (AWS CLI / SDK), comme l’exemple Python ci-dessous. import os
import boto3
from datetime import datetime
# Initialize the CloudWatch client
cloudwatch = boto3.client(&rsquo;logs&rsquo;, region_name=&lsquo;us-east-1&rsquo;)
# Define your log group name
log_group_name = &lsquo;reverse_proxy&rsquo;
# Path to your log directory
log_directory = &ldquo;/home/ec2-user/caddy/logs&rdquo;
def send_log_to_cloudwatch(log_stream_name, log_message):
try:
# Get or create the log stream
streams = cloudwatch.describe_log_streams(logGroupName=log_group_name, logStreamNamePrefix=log_stream_name)
if not streams[&rsquo;logStreams&rsquo;]:
cloudwatch.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)
# Send log to CloudWatch
cloudwatch.put_log_events(
logGroupName=log_group_name,
logStreamName=log_stream_name,
logEvents=[
{
&rsquo;timestamp&rsquo;: int(datetime.now().timestamp() * 1000),
&lsquo;message&rsquo;: log_message
}
]
)
except Exception as e:
print(f&quot;Failed to send log to CloudWatch: {str(e)}&quot;)
# Read logs from files and send to CloudWatch
for filename in os.listdir(log_directory):
if filename.endswith(&quot;.log&quot;):
log_stream_name = filename[:-4] # Remove .log from filename to use as stream name
file_path = os.path.join(log_directory, filename)
with open(file_path, &lsquo;r&rsquo;) as file:
for line in file:
send_log_to_cloudwatch(log_stream_name, line.strip())
